request:
{
 "project": "Gemini Software Requirements Specification",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Near-line processing should be available for simple data reductions required for data integrity validation (i.e. remove instrument and observatory effects so the observer can make decisions about further observing actions)."
   ]
  },
  {
   "speaker": "EndUser",
   "act": "state",
   "content": [
    "Off-line pixel processing for full data reduction should also exist at the Gemini 8m Telescopes site, but does not have any interface to the Gemini 8m Telescopes software."
   ]
  },
  {
   "speaker": "Analyst",
   "act": "backchannel"
  }
 ],
 "turns": [
  {
   "id": "M1:T81",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'user constraints' and asks about it."
  },
  {
   "id": "M1:T82",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "This will allow centralized support and coordination of their operations, providing both operations support for individual instruments and supervision for all of them.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T83",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Access from any user station will make user stations in principle identical and software configurable as the user station of this or that subsystem.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T84",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'software constraints' and asks about it."
  },
  {
   "id": "M1:T85",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Additions of new instruments should aim, as a goal, at introducing no modification to already operational parts. Modifications should be confined to the operational procedures and should not affect the bulk of the existing software.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T86",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": ".Switching to different configurations must be possible at any time with appropriate procedures.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T87",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'reliability and availability requirements' and asks about it."
  },
  {
   "id": "M1:T88",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "On-line pre-checking of the operational status of equipment should be done prior to sending critical or time consuming commands.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T89",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'maintainability' and asks about it."
  },
  {
   "id": "M1:T90",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The plan will consider: Maintenance requirements including an estimate of required resources; The method of upgrading the system to add capabilities and performance. Areas where upgrades are anticipated should be identified with an estimate of the required effort and resources.",
     "role": "statement"
    },
    {
     "text": "The plan will be delivered with the control system",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T91",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'quantitative maintenance requirements' and asks about it."
  },
  {
   "id": "M1:T92",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Quantitative maintenance requirements will be allocated to the system, subsystems, and each component.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T93",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Quantitative maintenance requirements will be allocated to the system, subsystems, and each component.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T94",
   "speaker": "EndUser",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T95",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'security and safety requirements' and asks about it."
  },
  {
   "id": "M1:T96",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The software should be able to quickly bring the Gemini system to a safe state upon notification of such danger.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T97",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T98",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In the event that the risk persists, subsystems must be able to move themselves into safe states to protect people and equipment (i.e. if there is a failure in the higher-level systems).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T99",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T100",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Safety protection must be applied whenever there is the risk that the actions of the control software could endanger people or cause damage to any Gemini 8m Telescopes subsystem, for example, by driving beyond limits or by overexposing detectors.",
     "role": "statement"
    }
   ]
  }
 ]
}
